def save(p,s):
 if '--check' in sys.argv: assert p.exists() and p.read_text()==s,f'Stale: {p}'
 else: p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def fmt(x):
 x=float(x)
 return str(int(x)) if x.is_integer() else f'{x:.4f}'.rstrip('0').rstrip('.')
def add(t,q,a,family,origin='AUTHORED_COMMON_BOARD_STYLE',metadata=None,**kw):
 items.append(dict(type=t,text=q,explanation=a,page=kw.pop('page','নিজস্ব সাধারণ বোর্ড-ধাঁচের অনুশীলনী; আসল বোর্ড প্রশ্ন নয়'),difficulty='MEDIUM',**kw))
 ledger.append({**dict(origin=origin,family=family,answerOrigin='ASSISTANT_AUTHORED_NOT_SOURCE_KEY',teacherApproved=False,sourceQuestionVerbatim=False),**(metadata or {})})
def mc(q,a,w,why,family,**kw):
 assert len(w)==3 and len(set([a,*w]))==4,(q,a,w)
 pos=sum(x['type']=='MCQ' for x in items)%4;opts=w.copy();opts.insert(pos,a)
 add('MCQ',q,why,family,options=dict(zip('ABCD',opts)),correct='ABCD'[pos],**kw)
def numeric(q,a,why,family,**kw):
 a=fmt(a);w=[]
 for v in [float(a)*2,float(a)/2,float(a)+1,float(a)+2,float(a)*3,float(a)+3]:
  s=fmt(v)
  if s!=a and s not in w:w.append(s)
  if len(w)==3:break
 mc(q,a,w,why,family,**kw)
def cq(q,parts,family,**kw):
 assert len(parts)==4
 add('CQ',q,'নিজস্ব উপপ্রশ্নভিত্তিক নমুনা সমাধান; শিক্ষক যাচাই বাকি।',family,parts=[dict(label=l,question=z[0],solution=z[1],marks=i) for i,(l,z) in enumerate(zip('কখগঘ',parts),1)],**kw)
def sq(q,a,family,**kw):add('SQ',q,a,family,**kw)
