HEATS=[('N₂(g)+3H₂(g)→2NH₃(g)',-92,'NH₃',2),('2SO₂(g)+O₂(g)→2SO₃(g)',-198,'SO₃',2),('N₂(g)+O₂(g)→2NO(g)',180,'NO',2),('CaCO₃(s)→CaO(s)+CO₂(g)',178,'CO₂',1),('CH₄(g)+2O₂(g)→CO₂(g)+2H₂O(l)',-890,'CO₂',1),('H⁺(aq)+OH⁻(aq)→H₂O(l)',-57,'H₂O',1)]
for eq,dh,prod,coef in HEATS:
 for extent in [1,3]:
  amount=coef*extent;energy=abs(dh)*extent;verb='নির্গত' if dh<0 else 'শোষিত';kind='তাপোৎপাদী' if dh<0 else 'তাপহারী';meta=dict(variant='STOICHIOMETRIC_HEAT_DATA_VARIANT',inputs=dict(eq=eq,dh=dh,coefficient=coef,extent=extent,product=prod))
