  numeric(stem+'\nকত kJ তাপ '+verb+' হবে?',energy,f'উৎপাদের মোল={amount}; সমীকরণের {coef} mol-এর {abs(dh)} kJ। তাই ({amount}/{coef})×{abs(dh)}={energy} kJ {verb}।','heat-amount',metadata=meta)
  mc(stem+'\nবিপরীত প্রক্রিয়ায় একই পরিমাণ পদার্থের জন্য ΔH কত kJ?',signed(-dh*extent),[signed(dh*extent),signed(-dh*extent*2),'0'],f'বিপরীত দিকে ΔH-এর চিহ্ন বদলায় এবং পরিমাণ অনুযায়ী মান={signed(-dh*extent)} kJ।','heat-reverse',metadata=meta)
  numeric(stem+'\nএই পরিমাণের অর্ধেক '+prod+' উৎপন্ন হলে তাপের পরিমাণ কত kJ?',Fraction(energy,2),f'একই শর্তে বিক্রিয়ার পরিমাণের সমানুপাতে তাপ; {energy}/2={fmt(Fraction(energy,2))} kJ {verb}।','heat-scaling',metadata=meta)
  cq(stem,[('তাপোৎপাদী বিক্রিয়া কাকে বলে?','যে বিক্রিয়ায় ব্যবস্থা থেকে পরিবেশে তাপ নির্গত হয়; ΔH ঋণাত্মক।'),('ΔH-এর চিহ্ন দিয়ে তাপের দিক বোঝানো হয় কেন?','ব্যবস্থা তাপ হারালে ΔH<0, তাপ শোষণ করলে ΔH>0; মান সবসময় উল্লিখিত সমীকরণ ও অবস্থার জন্য।'),('প্রদত্ত পরিমাণ উৎপাদ গঠনে তাপের পরিমাণ হিসাব করো।',f'({amount}/{coef})×{abs(dh)}={energy} kJ {verb}; বিক্রিয়াটি {kind}।'),('বিপরীত প্রক্রিয়া ও অর্ধেক বিক্রিয়ার পরিমাণের ক্ষেত্রে তাপ তুলনা করো।',f'বিপরীতে একই পরিমাণের ΔH={signed(-dh*extent)} kJ। সম্মুখে অর্ধেক পরিমাণে ΔH={fmt(Fraction(dh*extent,2))} kJ। ভৌত অবস্থা একই ধরা হয়েছে।')],'heat-analysis',metadata=meta)
